let body = $json.body ?? $json;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = null; } }
const missing = [];
const invalid = [];
const blank = (v) => v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return { valid: false, http_status: 400, response_body: { success: false, error_type: 'invalid_structure', message: 'El cuerpo debe ser un objeto JSON' } };
}
const i = body.incident || {};
for (const [path, value] of [['event_id', body.event_id], ['incident.id', i.id], ['incident.reference', i.reference], ['incident.customer_name', i.customer_name], ['incident.customer_email', i.customer_email], ['incident.subject', i.subject], ['incident.description', i.description], ['incident.telegram_chat_id', i.telegram_chat_id]]) {
  if (blank(value)) missing.push(path);
}
if (body.event_type !== 'support.requested') invalid.push({ field: 'event_type', message: 'Debe ser support.requested' });
if (!blank(i.id) && !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(i.id))) invalid.push({ field: 'incident.id', message: 'UUID no válido' });
if (!blank(i.customer_email) && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(i.customer_email))) invalid.push({ field: 'incident.customer_email', message: 'Correo no válido' });
if (!blank(body.timestamp) && Number.isNaN(Date.parse(body.timestamp))) invalid.push({ field: 'timestamp', message: 'Fecha no válida' });
const valid = missing.length === 0 && invalid.length === 0;
return {
  valid, missing_fields: missing, invalid_fields: invalid,
  event_id: body.event_id || null, incident_id: i.id || null, reference: i.reference || null,
  order_id: i.order_id || null, customer_name: i.customer_name || null,
  customer_email: i.customer_email ? String(i.customer_email).trim().toLowerCase() : null,
  subject: i.subject || null, description: i.description || null,
  priority: i.priority || 'medium', status: i.status || 'open',
  telegram_chat_id: i.telegram_chat_id || null, created_at: body.timestamp || new Date().toISOString(),
  http_status: valid ? 200 : 400,
  response_body: valid ? null : { success: false, error_type: missing.length ? 'missing_fields' : 'invalid_values', missing_fields: missing, invalid_fields: invalid, message: 'Evento support.requested inválido' }
};

const event = $('Validar incidencia').first().json;
const already = Boolean($json.telegram_message_id);
return {
  ...event, already_notified: already, should_send: !already,
  response_body: already ? { success: true, event_id: event.event_id, incident_id: event.incident_id, reference: event.reference, integration_status: 'already_processed', message: 'Incidencia ya creada y notificada' } : null
};

