const event = $('Validar incidencia').first().json;
const failed = $json.integration_status === 'retry';
return {
  http_status: failed ? 503 : 200,
  response_body: { success: !failed, event_id: event.event_id, incident_id: event.incident_id, reference: event.reference, integration_status: failed ? 'retry' : 'completed', message: failed ? 'Telegram falló; el backend reintentará' : 'Incidencia creada y notificada por Telegram' }
};
